-- Migration: hot key bounding the stored event window of one perf run
-- (sliding process-tail window, event leg). The ingest write gate trims the
-- stored rows of a run to the newest N right after each batch
-- (PerfConfigReader.eventsTailCap -> PerfMetricServiceImpl.trimEventTail);
-- absent or out-of-range rows fall back to the code default 2000, so a dirty
-- value can never switch the bound off nor collapse the window under one
-- screen. Applied manually to the dev DB (Flyway not enabled; db/migration is
-- reference + replay source for schema-init, regenerated by the single
-- regenerator via tools/ops/gen_schema_init.sh).
INSERT INTO tp_sys_config (config_key, config_value, group_name, value_type, encrypt_flag, description) VALUES
    ('perf.run.events-tail-cap', '2000', '系统', 'int', 0, '压测运行事件流每个运行保留的条数上限（默认 2000；可设 10~20000，保存即生效；超出后最早的事件会被自动清理，运行结果数据不受影响）')
ON CONFLICT (config_key) DO NOTHING;
